3	// Non-success Spotify response -> the Error we throw. Returns null for 2xx.
4	// `overrides` adds endpoint-specific status codes (e.g. player controls' 403/404).
5	function spotifyError(response, overrides = {}) {
6	  const byStatus = {
7	    401: () => new Error("TOKEN_EXPIRED"),
8	    429: () =>
9	      new Error(
10	        `RATE_LIMITED:${response.headers.get("Retry-After") ?? RATE_LIMITED_DEFAULT}`,
11	      ),
12	    ...overrides,
13	  };
14	  if (byStatus[response.status]) return byStatus[response.status]();
15	  return response.ok ? null : new Error(`SPOTIFY_ERROR:${response.status}`);
16	}
