18	export async function fetchCurrentlyPlaying(token) {
19	  const response = await fetch(
20	    "https://api.spotify.com/v1/me/player/currently-playing",
21	    {
22	      headers: { Authorization: `Bearer ${token}` },
23	    },
24	  );
25	
26	  if (response.status === 204) return null;
27	  const err = spotifyError(response);
28	  if (err) throw err;
29	
30	  const data = await response.json();
31	  if (!data.item) return null;
32	
33	  return {
34	    trackName: data.item.name,
35	    artistName: data.item.artists[0]?.name ?? null, // PRIMARY artist — keep, used elsewhere for geo lookup
36	    artistNames: data.item.artists.map((a) => a.name).join(", ") || null, // all artists joined, for display
37	    albumImageUrl: data.item.album.images[0]?.url ?? null,
38	    trackId: data.item.id,
39	    isPlaying: data.is_playing,
40	    progressMs: data.progress_ms,
41	    durationMs: data.item.duration_ms,
42	  };
43	}
