45	async function playerCommand(method, command, token) {
46	  const response = await fetch(
47	    `https://api.spotify.com/v1/me/player/${command}`,
48	    {
49	      method,
50	      headers: { Authorization: `Bearer ${token}` },
51	    },
52	  );
53	  if (response.status === 204) return; // success (no body)
54	  const err = spotifyError(response, {
55	    403: () => new Error("PLAYBACK_UNAVAILABLE"), // non-Premium / restricted
56	    404: () => new Error("NO_ACTIVE_DEVICE"),
57	  });
58	  if (err) throw err;
59	}
